typedef void (*qttune_frame_callback_t)(
    const qttune_frame_t* frame,
    void* user_data
);

typedef enum {
    QT_OK = 0,
    QT_ERR_NULL_ARGUMENT = 1,
    QT_ERR_NOT_IMPLEMENTED = 2,
    QT_ERR_NO_TRANSPORT = 3,
    QT_ERR_OUT_OF_MEMORY = 4,
    QT_ERR_SESSION_CLOSED = 5,
    QT_ERR_ALREADY_REGISTERED = 6,  /* Kept for backward compat if needed */
    QT_ERR_LOAD_FAILED = 7,
    QT_ERR_VEHICLE_TIMEOUT = 8,
    QT_ERR_TRANSPORT_HARD_FAILURE = 9,

    /* Append-only rule: new codes go HERE, never renumber */
} qttune_status_t;

typedef struct qttune_transport_ops {
    qttune_status_t (*start)(qttune_session_t* session, void* impl);
    void (*detach)(qttune_session_t* session, void* impl);
} qttune_transport_ops_t;

typedef struct qttune_transport {
    const qttune_transport_ops_t* ops;
    void* impl;
} qttune_transport_t;

typedef struct qttune_j2534_device {
    uint32_t vendor_id;           /* Index in discovery order (0-based) */
    char vendor_name[QTTUNE_J2534_VENDOR_NAME_LEN];
    char dll_path[QTTUNE_J2534_DLL_PATH_LEN];
    uint32_t supported_protocols; /* 0 — reserved for PROTOCOLS bitmask parse */
    uint32_t reserved[8];         /* ABI-stable expansion room
                                   * [0]: architecture (1=x86, 2=x64, 0=unknown) */
} qttune_j2534_device_t;

typedef struct qttune_pt_sconfig {
    unsigned long Parameter;   /* config parameter name (e.g. DATA_RATE) */
    unsigned long Value;      /* parameter value */
} SCONFIG;

typedef struct qttune_pt_sconfig_list {
    unsigned long NumOfParams;
    SCONFIG* ConfigPtr;
} SCONFIG_LIST;

typedef struct qttune_pt_passthru_msg {
    unsigned long ProtocolID;
    unsigned long RxStatus;
    unsigned long TxFlags;
    unsigned long Timestamp;       /* microseconds (spec v4.04; vendor
                                    * conformance is a BENCH check) */
    unsigned long DataSize;        /* payload bytes in Data[] */
    unsigned long ExtraDataIndex;  /* start of extra data (CRC, etc.);
                                    * == DataSize when none */
    unsigned char  Data[QTTUNE_PT_MSG_DATA_SIZE];
} PASSTHRU_MSG;

typedef struct QttuneSignalDef {
    uint16_t id;
    char name[32];
    QttuneSignalType type;
    uint8_t start_byte;
    uint8_t num_bytes;
    uint8_t bit_offset;
    uint8_t bit_length;
    float scale;
    float offset;
    char unit[16];
    uint8_t decimal_places;
    uint32_t flags;

    /* CAN arbitration ID this signal rides on. Consumers gate decode
     * on frame->arbitration_id == message_id BEFORE extraction;
     * qttune_decode_signal itself remains payload-only. */
    uint32_t message_id;

    /* MUX descriptor: packed [offset:8][length:8][reserved:16]
     * - offset: byte offset in payload where mux key sits (0..payload_len-1)
     * - length: 0 = mux disabled; 1 or 2 = key size in bytes
     * - reserved: must be zero
     * When mux is enabled (length > 0), decode proceeds ONLY if
     * the payload's key bytes match mux_key exactly. This enables
     * OBD-II response discrimination (e.g., 0x41 <PID> echo). */
    uint8_t mux_offset;
    uint8_t mux_length;
    uint8_t mux_reserved[2];
    uint32_t mux_key;  /* The byte pattern to match at mux_offset */
} QttuneSignalDef;

typedef struct QttuneSignalSet {
    uint32_t version;
    uint32_t count;
    const QttuneSignalDef* defs;
} QttuneSignalSet;

typedef struct qttune_sur_request {
    uint32_t request_id;    /* echoed in response; detects desync */
    uint32_t opcode;
    union {
        struct { uint32_t protocol_id; uint32_t flags; uint32_t baud; } connect;
        struct { uint32_t channel_id; } disconnect;
        /* Ioctl: flattened (Parameter, Value) u32 pairs, little-endian
         * memcpy order (both sides are x86/x64 LE — strong Win32 pair).
         * input_len must be a multiple of 8 for GET/SET_CONFIG; 0 for
         * ioctls taking NULL input. Output lands in the response. */
        struct { uint32_t channel_id; uint32_t ioctl_id;
                 uint8_t input[QTTUNE_SUR_IOCTL_DATA_MAX];
                 uint32_t input_len; } ioctl;
        /* Write: ONE PASSTHRU_MSG per request. tx_flags carries
         * TxFlags (CAN_29BIT_ID for 29-bit). Vendor timeout passed
         * through verbatim — 0 is the non-blocking choice for the
         * synchronous control-pump relay. */
        struct { uint32_t channel_id;
                 uint8_t data[QTTUNE_SUR_MSG_MAX];
                 uint32_t data_len; uint32_t tx_flags;
                 uint32_t timeout_ms; } write;
        struct { uint32_t timeout_ms; } read;
        struct { uint8_t data[QTTUNE_SUR_MSG_MAX]; uint32_t len;
                 uint32_t timestamp; uint32_t rx_flags; } inject;
        /* Filter: mask/pattern(/flow-control) as flat byte arrays —
         * the surrogate expands each into a full PASSTHRU_MSG
         * (ProtocolID=ISO15765, TxFlags from tx_flags, DataSize=len,
         * Data=bytes). flow-control is optional: fc_len==0 means the
         * vendor receives NULL (PASS/BLOCK filter semantics). */
        struct { uint32_t channel_id; uint32_t filter_type; uint32_t tx_flags;
                 uint8_t mask[QTTUNE_SUR_FILTER_PATTERN_MAX];
                 uint8_t pattern[QTTUNE_SUR_FILTER_PATTERN_MAX];
                 uint8_t flow_control[QTTUNE_SUR_FILTER_PATTERN_MAX];
                 uint32_t mask_len; uint32_t pattern_

typedef struct qttune_sur_response {
    uint32_t request_id;
    int32_t  status;             /* J2534 vendor status, verbatim */
    uint32_t handle_or_channel;
    uint32_t aux;
    uint8_t  data[QTTUNE_SUR_IOCTL_DATA_MAX];
    uint32_t data_len;
} qttune_sur_response_t;

typedef struct qttune_sur_ring_slot {
    uint8_t  data[64];
    uint32_t data_len;
    uint32_t protocol_id;
    uint32_t rx_status;
    uint32_t timestamp;       /* vendor units, passthrough (ptypes contract) */
    uint32_t extra_data_index;
} qttune_sur_ring_slot_t;

typedef struct qttune_sur_ring {
    volatile uint32_t head;
    volatile uint32_t tail;
    uint32_t reserved[2];
    qttune_sur_ring_slot_t slots[QTTUNE_SURROGATE_RING_SIZE];
} qttune_sur_ring_t;

typedef struct qttune_pid_scheduler {
    uint8_t pids[QTTUNE_SCHED_MAX_PIDS];
    uint32_t count;
    uint32_t cursor;
} qttune_pid_scheduler;

typedef void (*fn_get_last_filter_start)(unsigned long*, unsigned long*,
                                         unsigned char*, unsigned char*,
                                         unsigned long*);
